"use client";

import { useState } from "react";
import { Tv, Upload, X, Database } from "lucide-react";
import Input from "@/components/ui/Input";
import Button from "@/components/ui/Button";
import Badge from "@/components/ui/Badge";
import TMDBFetchModal from "./TMDBFetchModal";
import { LANGUAGES, CATEGORIES, GENRES, QUALITIES } from "@/utils/constants";
import SeasonEpisodeBuilder from "./SeasonEpisodeBuilder";
import { ISeason } from "@/models/Content";

interface UploadSeriesFormProps {
  onSubmit: (data: any) => void;
  isLoading?: boolean;
}

export default function UploadSeriesForm({ onSubmit, isLoading }: UploadSeriesFormProps) {
  const [formData, setFormData] = useState({
    type: "series",
    title: "",
    poster: "",
    banner: "",
    description: "",
    year: "",
    language: "",
    category: "Web Series",
    genre: "",
    quality: "",
    rating: "",
    tags: [] as string[],
    seasons: [] as ISeason[],
  });
  const [tagInput, setTagInput] = useState("");
  const [showTMDbModal, setShowTMDbModal] = useState(false);

  const handleTMDBFetch = (result: {
    title: string;
    poster: string;
    backdrop: string;
    description: string;
    year: string;
    rating: number;
    genres: string[];
    category: string;
  }) => {
    setFormData((prev) => ({
      ...prev,
      title: result.title,
      poster: result.poster,
      banner: result.backdrop,
      description: result.description,
      year: result.year,
      rating: result.rating.toString(),
      genre: result.genres[0] || "",
      category: result.category || "Web Series",
    }));
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleAddTag = () => {
    if (tagInput.trim() && !formData.tags.includes(tagInput.trim())) {
      setFormData((prev) => ({ ...prev, tags: [...prev.tags, tagInput.trim()] }));
      setTagInput("");
    }
  };

  const handleRemoveTag = (tag: string) => {
    setFormData((prev) => ({ ...prev, tags: prev.tags.filter((t) => t !== tag) }));
  };

  const handleSeasonsChange = (seasons: ISeason[]) => {
    setFormData((prev) => ({ ...prev, seasons }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit({
      ...formData,
      rating: formData.rating ? parseFloat(formData.rating) : undefined,
    });
  };

  return (
    <form
      onSubmit={handleSubmit}
      className="bg-[#161f2e] rounded-lg p-6 space-y-6 border border-gray-800"
    >
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 rounded-lg bg-[#e50914] flex items-center justify-center">
          <Tv className="w-5 h-5 text-white" />
        </div>
        <h2 className="text-xl font-bold text-white">Upload Web Series</h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Title */}
        <div className="relative">
          <Input
            label="Title *"
            name="title"
            value={formData.title}
            onChange={handleChange}
            placeholder="Enter series title"
            required
          />
          <button
            type="button"
            onClick={() => setShowTMDbModal(true)}
            className="absolute right-0 top-0 flex items-center gap-1 text-xs text-secondary hover:text-secondary/80"
          >
            <Database className="w-3 h-3" />
            Auto-fill
          </button>
        </div>

        {/* Year */}
        <Input
          label="Year"
          name="year"
          value={formData.year}
          onChange={handleChange}
          placeholder="e.g., 2024"
        />

        {/* Poster URL */}
        <Input
          label="Poster URL *"
          name="poster"
          value={formData.poster}
          onChange={handleChange}
          placeholder="https://example.com/poster.jpg"
          required
        />

        {/* Banner URL */}
        <Input
          label="Banner URL"
          name="banner"
          value={formData.banner}
          onChange={handleChange}
          placeholder="https://example.com/banner.jpg"
        />

        {/* Language */}
        <div>
          <label className="block text-sm font-medium text-text mb-1.5">Language</label>
          <select
            name="language"
            value={formData.language}
            onChange={handleChange}
            className="w-full px-4 py-2.5 rounded-xl bg-background border border-border text-text focus:outline-none focus:ring-2 focus:ring-primary/50"
          >
            <option value="">Select Language</option>
            {LANGUAGES.map((lang) => (
              <option key={lang} value={lang}>
                {lang}
              </option>
            ))}
          </select>
        </div>

        {/* Genre */}
        <div>
          <label className="block text-sm font-medium text-text mb-1.5">Genre</label>
          <select
            name="genre"
            value={formData.genre}
            onChange={handleChange}
            className="w-full px-4 py-2.5 rounded-xl bg-background border border-border text-text focus:outline-none focus:ring-2 focus:ring-primary/50"
          >
            <option value="">Select Genre</option>
            {GENRES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </div>

        {/* Rating */}
        <Input
          label="Rating (0-10)"
          name="rating"
          type="number"
          min="0"
          max="10"
          step="0.1"
          value={formData.rating}
          onChange={handleChange}
          placeholder="e.g., 8.5"
        />
      </div>

      {/* Description */}
      <div>
        <label className="block text-sm font-medium text-text mb-1.5">Description</label>
        <textarea
          name="description"
          value={formData.description}
          onChange={handleChange}
          rows={4}
          placeholder="Enter series description..."
          className="w-full px-4 py-2.5 rounded-xl bg-background border border-border text-text placeholder:text-muted focus:outline-none focus:ring-2 focus:ring-primary/50 resize-none"
        />
      </div>

      {/* Tags */}
      <div>
        <label className="block text-sm font-medium text-text mb-1.5">Tags</label>
        <div className="flex gap-2">
          <input
            type="text"
            value={tagInput}
            onChange={(e) => setTagInput(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && (e.preventDefault(), handleAddTag())}
            placeholder="Add a tag and press Enter"
            className="flex-1 px-4 py-2.5 rounded-xl bg-background border border-border text-text placeholder:text-muted focus:outline-none focus:ring-2 focus:ring-primary/50"
          />
          <Button type="button" onClick={handleAddTag} variant="outline">
            Add
          </Button>
        </div>
        <div className="flex flex-wrap gap-2 mt-2">
          {formData.tags.map((tag) => (
            <Badge key={tag} variant="primary" className="flex items-center gap-1">
              {tag}
              <button
                type="button"
                onClick={() => handleRemoveTag(tag)}
                className="hover:text-white"
              >
                <X className="w-3 h-3" />
              </button>
            </Badge>
          ))}
        </div>
      </div>

      {/* Season & Episode Builder */}
      <SeasonEpisodeBuilder
        seasons={formData.seasons}
        onChange={handleSeasonsChange}
      />

      {/* Submit */}
      <div className="flex justify-end pt-4">
        <Button type="submit" size="lg" isLoading={isLoading} className="w-full sm:w-auto gap-2">
          <Upload className="w-5 h-5" />
          Upload Series
        </Button>
      </div>

      <TMDBFetchModal
        isOpen={showTMDbModal}
        onClose={() => setShowTMDbModal(false)}
        onFetch={handleTMDBFetch}
        mediaType="tv"
      />
    </form>
  );
}
